let total = 0;
for (let i = 1; i <= 4; i++) {
  total = total + i;
}
document.write(total);

let word = "SNAKE";
let out = "";
let i = word.length - 1;
while (i >= 0) {
  out = out + word.substring(i, i + 1);
  i = i - 1;
}
document.write(out);

function total(marks) {
  let sum = 0;
  for (let i = 1; i < marks.length; i++) {
    sum = sum + marks[i];
  }
  return sum;
}

const form = document.getElementById("app");
form.onsubmit = function () {
  const n = Number(form.mark.value);
  document.getElementByID("result").innerHTML = "Total: " + total([n, 10, 20]);
  return false;
};

let mark = 67;
let grade = "";
if (mark >= 70) {
  grade = "A";
} else if (mark >= 60) {
  grade = "B";
} else {
  grade = "C";
}
document.write(grade);

let nums = [4, 7, 2, 9, 5];
let biggest = nums[0];
for (let i = 1; i < nums.length; i++) {
  if (nums[i] > biggest) {
    biggest = nums[i];
  }
}
document.write(biggest);

